FutureBehavior.futureEq-pair→:
{X.ℓX = ℓX : Level} {X = ℓA : Type ℓX} {A.ℓA = ℓO : Level}
{A : Type ℓO} {O.ℓO : Level} {O : Type O.ℓO} {P.ℓP = step : Level}
{P = observe : Type step} (x : ℓA → A → ℓA) (y : ℓA → O)
(z : ℓA → observe) {x = forget : ℓA} {y = x₁ : ℓA} →
FutureEq x (λ y₁ → y y₁ , z y₁) forget x₁ →
FutureEq x y forget x₁ × FutureEq x z forget x₁

